        w.engine.fronts.get_mut(&k).unwrap().commitments[i] = 1.;
    }
    w.engine.alliances.push(Alliance {
        threat_id: threat,
        creation_period: 0,
        serial: 0,
        members: members.to_vec(),
        pooled_resources: 3.,
    });
    let attacker = w.engine.cells[3].owner;
    let conquered_member = members[2];
    w.engine
        .apply_claims(
            &w.config,
