diff --git a/crates/sugarscape-core/src/democratic_peace/alliances.rs b/crates/sugarscape-core/src/democratic_peace/alliances.rs
new file mode 100644
index 0000000000000000000000000000000000000000..41ea1c0e8b721bc264b64c5d5f0e93b31d35acb7
--- /dev/null
+++ b/crates/sugarscape-core/src/democratic_peace/alliances.rs
@@ -0,0 +1,176 @@
+//! Threat-driven defensive alignment and explicit one-pass obligations.
+use super::*;
+use super::{
+    territory::{key, side},
+    types::bump,
+    world::Engine,
+};
+use std::collections::{BTreeMap, BTreeSet};
+impl Engine {
+    fn threatening(
+        &self,
+        c: &DemocraticPeaceConfig,
+        actor: StateId,
+        neighbor: StateId,
+    ) -> Result<Option<f64>, String> {
+        if self.states[&actor].regime == Regime::Democratic
+            && self.states[&neighbor].regime == Regime::Democratic
+        {
+            return Ok(None);
+        }
+        let k = key(actor, neighbor);
+        let i = side(k, actor);
+        let f = &self.fronts[&k];
+        let b =
+            super::resources::threat_ratio(f.commitments[1 - i], f.commitments[i], c.zero_ratio)?;
+        Ok((b > c.min_threat).then_some(b))
+    }
+    pub(crate) fn align(&mut self, c: &DemocraticPeaceConfig) -> Result<(), String> {
+        self.pariahs.clear();
+        if c.mechanism == Mechanism::Tagging {
+            self.alliances.clear();
+            return Ok(());
+        }
+        let old = std::mem::take(&mut self.alliances);
+        let mut groups: BTreeMap<StateId, (u64, u64, Vec<StateId>)> = BTreeMap::new();
+        let mut assigned = BTreeSet::new();
+        if c.alliance_maintenance == AllianceMaintenance::PersistWhileThreatened {
+            for a in old {
+                if !self.states.contains_key(&a.threat_id) {
+                    continue;
+                }
+                let mut members = Vec::new();
+                for m in a.members {
+                    if self.states.contains_key(&m)
+                        && self.fronts.contains_key(&key(m, a.threat_id))
+                        && self.threatening(c, m, a.threat_id)?.is_some()
+                    {
+                        members.push(m);
+                    }
+                }
+                if members.len() >= 2 {
+                    assigned.extend(members.iter().copied());
+                    groups.insert(a.threat_id, (a.creation_period, a.serial, members));
+                }
+            }
+        }
+        let actors: Vec<_> = self.states.keys().copied().collect();
+        let mut proposals: BTreeMap<StateId, Vec<StateId>> = BTreeMap::new();
+        for actor in actors {
+            if assigned.contains(&actor) {
+                continue;
+            }
+            let mut best = None;
+            let mut ties = Vec::new();
+            for neighbor in self.neighbors(actor) {
+                if let Some(b) = self.threatening(c, actor, neighbor)? {
+                    if best.is_none_or(|v| b > v) {
+                        best = Some(b);
+                        ties.clear();
+                        ties.push(neighbor);
+                    } else if best == Some(b) {
+                        ties.push(neighbor);
+                    }
+                }
+            }
+            if !ties.is_empty() {
+                let target = if c.threat_ties == ThreatTies::RandomTie {
+                    super::world::pick(&ties, &mut self.rng).unwrap()
+                } else {
+                    ties[0]
+                };
+                proposals.entry(target).or_default().push(actor);
+            }
+        }
+        for (threat, mut members) in proposals {
+            if let Some((_, _, existing)) = groups.get_mut(&threat) {
+                existing.append(&mut members);
+                existing.sort();
+            } else if members.len() >= 2 {
+                let serial = self.next_alliance;
+                bump(&mut self.next_alliance)?;
+                groups.insert(threat, (self.period, serial, members));
+            }
+        }
+        for (threat, (creation_period, serial, members)) in groups {
+            let pooled_resources = members
+                .iter()
+                .map(|m| {
+                    let k = key(*m, threat);
+                    self.fronts[&k].commitments[side(k, *m)]
+                })
+                .sum();
+            if !f64::is_finite(pooled_resources) {
+                return Err("nonfinite alliance pool".into());
+            }
+            self.alliances.push(Alliance {
+                threat_id: threat,
+                creation_period,
+                serial,
+                members,
+                pooled_resources,
+            });
+        }
+        Ok(())
+    }
+    pub(crate) fn obligations(&mut self, c: &DemocraticPeaceConfig, current: bool) {
+        let actions: BTreeMap<_, _> = self
+            .fronts
+            .iter()
+            .map(|(&k, f)| (k, if current { f.actions } else { f.previous }))
+            .collect();
+        self.pariahs.clear();
+        if c.mechanism == Mechanism::CollectiveSecurity {
+            for (k, a) in &actions {
+                if a[0] && a[1] {
+                    let regimes = [self.states[&k[0]].regime, self.states[&k[1]].regime];
+                    if regimes[0] != regimes[1] {
+                        let d = usize::from(regimes[1] == Regime::Democratic);
+                        self.pariahs.entry(k[1 - d]).or_default().push(k[d]);
+                    }
+                }
+            }
+            for sources in self.pariahs.values_mut() {
+                sources.sort();
+                sources.dedup();
+            }
+        }
+        let mut obligations: Vec<([StateId; 2], usize, String)> = Vec::new();
+        for alliance in &self.alliances {
+            let attacked = alliance.members.iter().any(|m| {
+                let k = key(*m, alliance.threat_id);
+                actions
+                    .get(&k)
+                    .is_some_and(|a| a[side(k, alliance.threat_id)])
+            });
+            if attacked {
+                for m in &alliance.members {
+                    let k = key(*m, alliance.threat_id);
+                    if self.fronts.contains_key(&k) {
+                        obligations.push((k, side(k, *m), "attacked_ally".into()));
+                    }
+                }
+            }
+        }
+        for (&pariah, sources) in &self.pariahs {
+            for (&actor, s) in &self.states {
+                if s.regime != Regime::Democratic {
+                    continue;
+                }
+                let permitted = c.security_scope == SecurityScope::AllDemocracies
+                    || self.alliances.iter().any(|a| {
+                        a.members.contains(&actor) && sources.iter().any(|d| a.members.contains(d))
+                    });
+                let k = key(actor, pariah);
+                if permitted && self.fronts.contains_key(&k) {
+                    obligations.push((k, side(k, actor), "pariah".into()));
+                }
+            }
+        }
+        for (k, i, reason) in obligations {
+            let f = self.fronts.get_mut(&k).unwrap();
+            f.actions[i] = true;
+            f.obligations[i].push(reason);
+        }
+    }
+}
diff --git a/crates/sugarscape-core/src/democratic_peace/claims.rs b/crates/sugarscape-core/src/democratic_peace/claims.rs
new file mode 100644
index 0000000000000000000000000000000000000000..d65e1e5cdab1d60d150d2974669a5e0a3cd31c41
--- /dev/null
+++ b/crates/sugarscape-core/src/democratic_peace/claims.rs
@@ -0,0 +1,168 @@
+//! Prospective complete claim footprints and single-cell sovereign release.
+use super::*;
+use super::{
+    types::{bump, Claim},
+    world::Engine,
+};
+use std::collections::BTreeSet;
+impl Engine {
+    fn release(&mut self, cell: usize) -> Result<StateId, String> {
+        self.cells[cell].next_generation = self.cells[cell]
+            .next_generation
+            .checked_add(1)
+            .ok_or("sovereignty generation overflow")?;
+        let id = StateId {
+            capital_cell: cell,
+            sovereignty_generation: self.cells[cell].next_generation,
+        };
+        self.cells[cell].owner = id;
+        self.states.insert(
+            id,
+            State {
+                id,
+                regime: self.cells[cell].latent_regime,
+                resources: 10.,
+                members: vec![cell],
+            },
+        );
+        bump(&mut self.counters.released_states)?;
+        Ok(id)
+    }
+    pub(crate) fn apply_claims(
+        &mut self,
+        c: &DemocraticPeaceConfig,
+        claims: Vec<Claim>,
+    ) -> Result<(), String> {
+        if claims.is_empty() {
+            return Ok(());
+        }
+        let mut actors: Vec<_> = self.states.keys().copied().collect();
+        super::world::shuffle(&mut actors, &mut self.rng);
+        let mut locked_cells = BTreeSet::new();
+        let mut locked_states = BTreeSet::new();
+        for actor in actors {
+            let mut own: Vec<_> = claims
+                .iter()
+                .filter(|q| q.states[q.side] == actor)
+                .collect();
+            own.sort_by_key(|q| q.states);
+            for q in own {
+                let winner = q.states[q.side];
+                let loser = q.states[1 - q.side];
+                let agent = q.path[q.side];
+                let target = q.path[1 - q.side];
+                if !self.states.contains_key(&winner)
+                    || !self.states.contains_key(&loser)
+                    || self.cells[agent].owner != winner
+                    || self.cells[target].owner != loser
+                    || !self.adjacent(agent).contains(&target)
+                {
+                    bump(&mut self.counters.stale_claims)?;
+                    continue;
+                }
+                let members = self.member_cells(loser);
+                let capital = target == loser.capital_cell;
+                let releases: Vec<usize> = if capital && members.len() > 1 {
+                    members
+                        .iter()
+                        .copied()
+                        .filter(|&cell| {
+                            c.capital_capture == CapitalCapture::CollapseOnly || cell != target
+                        })
+                        .collect()
+                } else if !capital {
+                    let reached = self.reached(loser, Some(target));
+                    members
+                        .iter()
+                        .copied()
+                        .filter(|&cell| cell != target && !reached.contains(&cell))
+                        .collect()
+                } else {
+                    Vec::new()
+                };
+                let footprint: BTreeSet<_> = std::iter::once(target)
+                    .chain(releases.iter().copied())
+                    .collect();
+                let blocked = match c.claim_locking {
+                    ClaimLocking::AffectedCells => {
+                        locked_cells.contains(&agent)
+                            || footprint.iter().any(|cell| locked_cells.contains(cell))
+                    }
+                    ClaimLocking::AffectedStates => {
+                        locked_states.contains(&winner) || locked_states.contains(&loser)
+                    }
+                };
+                if blocked {
+                    bump(&mut self.counters.locked_claims)?;
+                    continue;
+                }
+                let retired = capital;
+                if retired {
+                    self.states.remove(&loser);
+                    bump(&mut self.counters.retired_states)?;
+                }
+                let absorb = !(capital
+                    && members.len() > 1
+                    && c.capital_capture == CapitalCapture::CollapseOnly);
+                if absorb {
+                    self.cells[target].owner = winner;
+                    if c.latent_regime == LatentRegime::OverwriteOnConquest {
+                        self.cells[target].latent_regime = self.states[&winner].regime;
+                    }
+                }
+                let mut new_ids = Vec::new();
+                for cell in releases {
+                    new_ids.push(self.release(cell)?);
+                }
+                if c.claim_locking == ClaimLocking::AffectedCells {
+                    locked_cells.extend(footprint.iter().copied());
+                    locked_cells.insert(agent);
+                } else {
+                    locked_states.extend([winner, loser]);
+                    locked_states.extend(new_ids);
+                }
+                bump(&mut self.counters.successful_claims)?;
+                let event = Event {
+                    period: self.period,
+                    kind: if capital && members.len() > 1 {
+                        "capital_collapse"
+                    } else {
+                        "conquest"
+                    }
+                    .into(),
+                    states: vec![winner, loser],
+                    cells: footprint.into_iter().collect(),
+                };
+                self.last_structural_event = Some(event.clone());
+                self.record(c, event)?;
+            }
+        }
+        self.rebuild()?;
+        let alive: BTreeSet<_> = self.states.keys().copied().collect();
+        let fronts = &self.fronts;
+        for a in &mut self.alliances {
+            a.members.retain(|m| {
+                alive.contains(m) && fronts.contains_key(&super::territory::key(*m, a.threat_id))
+            });
+            a.pooled_resources = a
+                .members
+                .iter()
+                .map(|member| {
+                    let k = super::territory::key(*member, a.threat_id);
+                    let i = super::territory::side(k, *member);
+                    self.fronts[&k].commitments[i]
+                })
+                .sum();
+            if !a.pooled_resources.is_finite() {
+                return Err("nonfinite surviving alliance pool".into());
+            }
+        }
+        self.alliances
+            .retain(|a| alive.contains(&a.threat_id) && a.members.len() >= 2);
+        self.pariahs.retain(|p, sources| {
+            sources.retain(|s| alive.contains(s));
+            alive.contains(p) && !sources.is_empty()
+        });
+        Ok(())
+    }
+}
diff --git a/crates/sugarscape-core/src/democratic_peace/combat.rs b/crates/sugarscape-core/src/democratic_peace/combat.rs
new file mode 100644
index 0000000000000000000000000000000000000000..4ee803b96d41c2bf9f79727aeadf89f42bdc8c03
--- /dev/null
+++ b/crates/sugarscape-core/src/democratic_peace/combat.rs
@@ -0,0 +1,98 @@
+//! Local mutual-defection battles with no resource damage.
+use super::*;
+use super::{
+    types::{bump, Claim},
+    world::Engine,
+};
+impl Engine {
+    pub(crate) fn combat(&mut self, c: &DemocraticPeaceConfig) -> Result<Vec<Claim>, String> {
+        let keys: Vec<_> = self.fronts.keys().copied().collect();
+        let mut claims = Vec::new();
+        for k in keys {
+            let acts = self.fronts[&k].actions;
+            if !acts.iter().any(|a| *a) {
+                continue;
+            }
+            let valid = self.fronts[&k].path.is_some_and(|p| {
+                self.cells[p[0]].owner == k[0]
+                    && self.cells[p[1]].owner == k[1]
+                    && self.adjacent(p[0]).contains(&p[1])
+            });
+            if !valid {
+                let actor = k[usize::from(!acts[0])];
+                let target = if actor == k[0] { k[1] } else { k[0] };
+                let p = self.path(actor, target)?;
+                let f = self.fronts.get_mut(&k).unwrap();
+                f.path = Some(p);
+                f.path_proposer = Some(actor);
+            }
+            if !(acts[0] && acts[1]) {
+                continue;
+            }
+            bump(&mut self.counters.mutual_d_front_periods)?;
+            let v = self.fronts[&k].commitments;
+            let q = [
+                super::resources::probability(
+                    v[0],
+                    v[1],
+                    c.victory_threshold,
+                    c.victory_exponent,
+                    c.probability_direction,
+                    c.zero_ratio,
+                )?,
+                super::resources::probability(
+                    v[1],
+                    v[0],
+                    c.victory_threshold,
+                    c.victory_exponent,
+                    c.probability_direction,
+                    c.zero_ratio,
+                )?,
+            ];
+            let success = if c.opposing_victories == OpposingVictories::IndependentClaims {
+                [
+                    super::world::chance(q[0], &mut self.rng),
+                    super::world::chance(q[1], &mut self.rng),
+                ]
+            } else {
+                let scale = (q[0] + q[1]).max(1.);
+                let r = super::world::draw(&mut self.rng);
+                [
+                    r < q[0] / scale,
+                    r >= q[0] / scale && r < (q[0] + q[1]) / scale,
+                ]
+            };
+            let victory = success.iter().any(|a| *a);
+            let stalemate =
+                !victory && super::world::chance(c.stalemate_probability, &mut self.rng);
+            let f = self.fronts.get_mut(&k).unwrap();
+            f.victory_probabilities = [Some(q[0]), Some(q[1])];
+            f.victory_ratios = [Some(Ratio::new(v[0], v[1])), Some(Ratio::new(v[1], v[0]))];
+            f.claims = success;
+            if victory {
+                bump(&mut self.counters.completed_victory_battles)?;
+                if success[0] && success[1] {
+                    bump(&mut self.counters.opposing_claims)?;
+                }
+                for (i, &won) in success.iter().enumerate() {
+                    if won {
+                        claims.push(Claim {
+                            states: k,
+                            side: i,
+                            path: f.path.unwrap(),
+                        });
+                    }
+                }
+            }
+            if stalemate {
+                bump(&mut self.counters.completed_stalemate_battles)?;
+            }
+            if victory || stalemate {
+                f.actions = [false; 2];
+                f.path = None;
+                f.path_proposer = None;
+            }
+        }
+        Ok(claims)
+    }
+}
