+use super::*;
+use crate::stats::Series;
+use serde::Serialize;
+pub const SERIES: &[&str] = &[
+    "period",
+    "periods",
+    "completed_periods",
+    "attempted_period",
+    "last_tick_periods",
+    "democratic_share",
+    "clustering_ratio",
+    "sovereign_count",
+    "democratic_states",
+    "predatory_states",
+    "conflict_fronts",
+    "alliance_count",
+    "pariah_count",
+];
+pub fn series_names() -> Vec<String> {
+    SERIES.iter().map(|s| s.to_string()).collect()
+}
+#[derive(Clone, Debug, Default, Serialize)]
+pub struct DemocraticPeaceSnapshot {
+    pub tick: u64,
+    pub period: u64,
+    pub periods: u64,
+    pub completed_periods: u64,
+    pub attempted_period: u64,
+    pub last_tick_periods: u32,
+    pub democratic_share: f64,
+    pub clustering_ratio: Option<f64>,
+    pub clustering_reason: Option<String>,
+    pub sovereign_count: u32,
+    pub democratic_states: u32,
+    pub predatory_states: u32,
+    pub conflict_fronts: u32,
+    pub alliance_count: u32,
+    pub pariah_count: u32,
+    pub finish_reason: Option<String>,
+    pub invalidity: Option<String>,
+    pub invalid_phase: Option<String>,
+    pub metrics: Metrics,
+}
+impl Series for DemocraticPeaceSnapshot {
+    fn tick(&self) -> u64 {
+        self.tick
+    }
+    fn value(&self, n: &str) -> Option<f64> {
+        Some(match n {
+            "tick" => self.tick as f64,
+            "period" | "periods" | "completed_periods" => self.period as f64,
+            "attempted_period" => self.attempted_period as f64,
+            "last_tick_periods" => self.last_tick_periods as f64,
+            "democratic_share" => self.democratic_share,
+            "clustering_ratio" => return self.clustering_ratio,
+            "sovereign_count" => self.sovereign_count as f64,
+            "democratic_states" => self.democratic_states as f64,
+            "predatory_states" => self.predatory_states as f64,
+            "conflict_fronts" => self.conflict_fronts as f64,
+            "alliance_count" => self.alliance_count as f64,
+            "pariah_count" => self.pariah_count as f64,
+            _ => return None,
+        })
+    }
+}
diff --git a/crates/sugarscape-core/src/democratic_peace/territory.rs b/crates/sugarscape-core/src/democratic_peace/territory.rs
new file mode 100644
index 0000000000000000000000000000000000000000..b609186f1d476a2195f20b85ef6a26579698cd51
--- /dev/null
+++ b/crates/sugarscape-core/src/democratic_peace/territory.rs
@@ -0,0 +1,339 @@
+//! Bounded cardinal topology and source distance choices.
+use super::world::Engine;
+use super::*;
+use std::collections::{BTreeSet, VecDeque};
+impl Engine {
+    pub(crate) fn adjacent(&self, id: usize) -> Vec<usize> {
+        let w = self.width as usize;
+        let n = self.cells.len();
+        let mut v = Vec::with_capacity(4);
+        if !id.is_multiple_of(w) {
+            v.push(id - 1);
+        }
+        if id % w + 1 < w {
+            v.push(id + 1);
+        }
+        if id >= w {
+            v.push(id - w);
+        }
+        if id + w < n {
+            v.push(id + w);
+        }
+        v.sort_unstable();
+        v
+    }
+    pub(crate) fn neighbors(&self, id: StateId) -> Vec<StateId> {
+        self.fronts
+            .keys()
+            .filter_map(|k| {
+                if k[0] == id {
+                    Some(k[1])
+                } else if k[1] == id {
+                    Some(k[0])
+                } else {
+                    None
+                }
+            })
+            .collect()
+    }
+    pub(crate) fn member_cells(&self, id: StateId) -> Vec<usize> {
+        self.cells
+            .iter()
+            .filter(|c| c.owner == id)
+            .map(|c| c.id)
+            .collect()
+    }
+    pub(crate) fn reached(&self, id: StateId, excluded: Option<usize>) -> BTreeSet<usize> {
+        let mut reached = BTreeSet::new();
+        let mut todo = vec![id.capital_cell];
+        while let Some(cell) = todo.pop() {
+            if Some(cell) == excluded || self.cells[cell].owner != id || !reached.insert(cell) {
+                continue;
+            }
+            for next in self.adjacent(cell) {
+                if Some(next) != excluded && self.cells[next].owner == id {
+                    todo.push(next);
+                }
+            }
+        }
+        reached
+    }
+    pub(crate) fn rebuild(&mut self) -> Result<(), String> {
+        for s in self.states.values_mut() {
+            s.members.clear();
+        }
+        for c in &self.cells {
+            self.states
+                .get_mut(&c.owner)
+                .ok_or("cell owner has no state")?
+                .members
+                .push(c.id);
+        }
+        let mut keys = BTreeSet::new();
+        for c in &self.cells {
+            for next in self.adjacent(c.id) {
+                let other = self.cells[next].owner;
+                if other != c.owner {
+                    keys.insert(key(c.owner, other));
+                }
+            }
+        }
+        let mut old = std::mem::take(&mut self.fronts);
+        self.fronts = keys
+            .into_iter()
+            .map(|k| (k, old.remove(&k).unwrap_or_else(|| Front::new(k))))
+            .collect();
+        Ok(())
+    }
+    pub(crate) fn distance(
+        &self,
+        c: &DemocraticPeaceConfig,
+        id: StateId,
+        cell: usize,
+    ) -> Result<f64, String> {
+        let w = self.width as usize;
+        let dx = (id.capital_cell % w).abs_diff(cell % w);
+        let dy = (id.capital_cell / w).abs_diff(cell / w);
+        match c.distance_metric {
+            DistanceMetric::Euclidean => Ok(libm::sqrt((dx * dx + dy * dy) as f64)),
+            DistanceMetric::Manhattan => Ok((dx + dy) as f64),
+            DistanceMetric::TerritorialPath => {
+                let mut todo = VecDeque::from([(id.capital_cell, 0)]);
+                let mut seen = BTreeSet::new();
+                while let Some((p, d)) = todo.pop_front() {
+                    if !seen.insert(p) {
+                        continue;
+                    }
+                    if p == cell {
+                        return Ok(d as f64);
+                    }
+                    for q in self.adjacent(p) {
+                        if self.cells[q].owner == id {
+                            todo.push_back((q, d + 1));
+                        }
+                    }
+                }
+                Err("unreachable territorial distance".into())
+            }
+        }
+    }
+    pub(crate) fn path(
+        &mut self,
+        attacker: StateId,
+        target: StateId,
+    ) -> Result<[usize; 2], String> {
+        let targets: Vec<_> = self
+            .cells
+            .iter()
+            .filter(|c| {
+                c.owner == target
+                    && self
+                        .adjacent(c.id)
+                        .iter()
+                        .any(|&q| self.cells[q].owner == attacker)
+            })
+            .map(|c| c.id)
+            .collect();
+        let victim =
+            super::world::pick(&targets, &mut self.rng).ok_or("no bordering target cell")?;
+        let agents: Vec<_> = self
+            .adjacent(victim)
+            .into_iter()
+            .filter(|&q| self.cells[q].owner == attacker)
+            .collect();
+        let agent = super::world::pick(&agents, &mut self.rng).ok_or("no bordering agent cell")?;
+        Ok(if attacker < target {
+            [agent, victim]
+        } else {
+            [victim, agent]
+        })
+    }
+    pub(crate) fn validate(&self) -> Result<(), String> {
+        if self.width == 0 || !self.cells.len().is_multiple_of(self.width as usize) {
+            return Err(format!(
+                "grid width {} does not divide {} cells",
+                self.width,
+                self.cells.len()
+            ));
+        }
+        for (index, cell) in self.cells.iter().enumerate() {
+            if cell.id != index {
+                return Err(format!(
+                    "cell at vector index {index} has mismatched cell id {}",
+                    cell.id
+                ));
+            }
+            if !self.states.contains_key(&cell.owner) {
+                return Err(format!(
+                    "cell {index} is owned by missing state {:?}",
+                    cell.owner
+                ));
+            }
+        }
+        for (id, state) in &self.states {
+            if state.id != *id {
+                return Err(format!(
+                    "state map key {:?} disagrees with stored state id {:?}",
+                    id, state.id
+                ));
+            }
+            if id.capital_cell >= self.cells.len() {
+                return Err(format!(
+                    "state {:?} capital cell {} is outside {} cells",
+                    id,
+                    id.capital_cell,
+                    self.cells.len()
+                ));
+            }
+            if self.cells[id.capital_cell].owner != *id {
+                return Err(format!(
+                    "state {:?} capital cell {} is owned by {:?}",
+                    id, id.capital_cell, self.cells[id.capital_cell].owner
+                ));
+            }
+            if self.cells[id.capital_cell].next_generation != id.sovereignty_generation {
+                return Err(format!(
+                    "state {:?} generation {} does not match capital cell {} generation counter {}",
+                    id,
+                    id.sovereignty_generation,
+                    id.capital_cell,
+                    self.cells[id.capital_cell].next_generation
+                ));
+            }
+            if state.regime != self.cells[id.capital_cell].latent_regime {
+                return Err(format!(
+                    "state {:?} regime disagrees with capital cell {} latent regime",
+                    id, id.capital_cell
+                ));
+            }
+            if !state.resources.is_finite() || state.resources < 0. {
+                return Err(format!("state {:?} has invalid resources", id));
+            }
+            let owned: Vec<_> = self
+                .cells
+                .iter()
+                .enumerate()
+                .filter_map(|(index, cell)| (cell.owner == *id).then_some(index))
+                .collect();
+            if owned.is_empty() {
+                return Err(format!("state {:?} owns no cells", id));
+            }
+            if state.members != owned {
+                return Err(format!(
+                    "state {:?} member list {:?} does not equal owned cells {:?}",
+                    id, state.members, owned
+                ));
+            }
+            let reached = self.reached(*id, None);
+            if reached.iter().copied().collect::<Vec<_>>() != owned {
+                return Err(format!(
+                    "state {:?} owned cells {:?} are not connected from capital {}",
+                    id, owned, id.capital_cell
+                ));
+            }
+        }
+
+        let mut expected_fronts = BTreeSet::new();
+        for cell in 0..self.cells.len() {
+            let owner = self.cells[cell].owner;
+            for neighbor in self.adjacent(cell) {
+                let other = self.cells[neighbor].owner;
+                if owner != other {
+                    expected_fronts.insert(key(owner, other));
+                }
+            }
+        }
+        for (front_key, front) in &self.fronts {
+            if front.states != *front_key || key(front.states[0], front.states[1]) != *front_key {
+                return Err(format!(
+                    "front map key {:?} disagrees with front endpoint ids {:?}",
+                    front_key, front.states
+                ));
+            }
+            for state in front.states {
+                if !self.states.contains_key(&state) {
+                    return Err(format!(
+                        "front {:?} references missing endpoint state {:?}",
+                        front_key, state
+                    ));
+                }
+            }
+            if front
+                .commitments
+                .iter()
+                .chain(front.old_commitments.iter())
+                .any(|r| !r.is_finite() || *r < 0.)
+            {
+                return Err(format!("front {:?} has invalid commitment", front_key));
+            }
+        }
+        let actual_fronts: BTreeSet<_> = self.fronts.keys().copied().collect();
+        if let Some(missing) = expected_fronts.difference(&actual_fronts).next() {
+            return Err(format!(
+                "front topology is missing territorial front {:?}",
+                missing
+            ));
+        }
+        if let Some(extra) = actual_fronts.difference(&expected_fronts).next() {
+            return Err(format!(
+                "front topology has nonterritorial front {:?}",
+                extra
+            ));
+        }
+
+        let mut membership = BTreeSet::new();
+        for alliance in &self.alliances {
+            if alliance.members.len() < 2
+                || !self.states.contains_key(&alliance.threat_id)
+                || !alliance.pooled_resources.is_finite()
+                || alliance.pooled_resources < 0.
+            {
+                return Err(format!(
+                    "alliance against {:?} has invalid identity or pool",
+                    alliance.threat_id
+                ));
+            }
+            if alliance.members.windows(2).any(|pair| pair[0] >= pair[1]) {
+                return Err(format!(
+                    "alliance against {:?} has unsorted or duplicate members {:?}",
+                    alliance.threat_id, alliance.members
+                ));
+            }
+            let mut expected_pool = 0.;
+            for member in &alliance.members {
+                if *member == alliance.threat_id
+                    || !self.states.contains_key(member)
+                    || !self.fronts.contains_key(&key(*member, alliance.threat_id))
+                {
+                    return Err(format!(
+                        "alliance against {:?} has invalid member {:?}",
+                        alliance.threat_id, member
+                    ));
+                }
+                if !membership.insert(*member) {
+                    return Err(format!("state {:?} belongs to multiple alliances", member));
+                }
+                let front_key = key(*member, alliance.threat_id);
+                let member_side = side(front_key, *member);
+                expected_pool += self.fronts[&front_key].commitments[member_side];
+            }
+            if !expected_pool.is_finite() || alliance.pooled_resources != expected_pool {
+                return Err(format!(
+                    "alliance against {:?} pool {} does not equal surviving member commitments {}",
+                    alliance.threat_id, alliance.pooled_resources, expected_pool
+                ));
+            }
+        }
+        Ok(())
+    }
+}
+pub(crate) fn key(a: StateId, b: StateId) -> [StateId; 2] {
+    if a < b {
+        [a, b]
+    } else {
+        [b, a]
+    }
+}
+pub(crate) fn side(k: [StateId; 2], id: StateId) -> usize {
+    usize::from(k[1] == id)
+}
diff --git a/crates/sugarscape-core/src/democratic_peace/tests.rs b/crates/sugarscape-core/src/democratic_peace/tests.rs
new file mode 100644
index 0000000000000000000000000000000000000000..222505f2ca2894d127f9ab4abef67ed142f019e6
--- /dev/null
+++ b/crates/sugarscape-core/src/democratic_peace/tests.rs
@@ -0,0 +1,892 @@
+use super::*;
+use crate::model::Model;
+fn small() -> DemocraticPeaceConfig {
+    DemocraticPeaceConfig {
+        width: 3,
+        height: 2,
+        horizon_periods: 7,
+        ..Default::default()
+    }
+}
+fn fixture(owners: &[usize], regimes: &[Regime]) -> DemocraticPeaceWorld {
+    let mut w = DemocraticPeaceWorld::new(small(), 9).unwrap();
+    w.engine.states.clear();
+    for (i, &capital) in owners.iter().enumerate() {
+        let id = StateId {
+            capital_cell: capital,
+            sovereignty_generation: 0,
+        };
+        w.engine.cells[i].owner = id;
+        w.engine.cells[i].latent_regime = regimes[i];
+        w.engine.states.entry(id).or_insert(State {
+            id,
+            regime: regimes[capital],
+            resources: 100.,
+            members: vec![],
+        });
+    }
+    w.engine.rebuild().unwrap();
+    w
+}
+#[test]
+fn rounded_quota_assigns_exact_counts() {
+    let w = DemocraticPeaceWorld::new(
+        DemocraticPeaceConfig {
+            assignment: Assignment::RoundedQuota,
+            initial_democratic_share: 0.5,
+            initial_resourced_share: 0.5,
+            ..small()
+        },
+        3,
+    )
+    .unwrap();
+    assert_eq!(w.setup.initial_democratic_cells, 3);
+    assert_eq!(w.setup.initial_resourced_cells, 3);
+}
+#[test]
+fn initial_all_democratic_first_passage_is_zero() {
+    let w = DemocraticPeaceWorld::new(
+        DemocraticPeaceConfig {
+            initial_democratic_share: 1.,
+            ..small()
+        },
+        3,
+    )
+    .unwrap();
+    assert_eq!(w.snapshot().metrics.first_all_democratic_period, Some(0));
+}
+#[test]
+fn grouped_periods_have_identical_state_and_rng() {
+    let mut a = DemocraticPeaceWorld::new(small(), 3).unwrap();
+    let mut b = DemocraticPeaceWorld::new(
+        DemocraticPeaceConfig {
+            periods_per_tick: 3,
+            ..small()
+        },
+        3,
+    )
+    .unwrap();
+    a.run(7);
+    b.run(3);
+    assert_eq!(a.economic_fingerprint(), b.economic_fingerprint());
+    assert_eq!(a.outcome(), b.outcome());
+}
+#[test]
+fn failed_period_preserves_engine_and_rng() {
+    let mut w = DemocraticPeaceWorld::new(
+        DemocraticPeaceConfig {
+            zero_ratio: ZeroRatio::RejectZeroDenominator,
+            initial_resourced_share: 0.,
+            initial_democratic_share: 0.,
+            ..small()
+        },
+        3,
+    )
+    .unwrap();
+    let before = w.economic_fingerprint();
+    w.run(1);
+    assert_eq!(w.economic_fingerprint(), before);
+    assert_eq!(w.completed_periods(), 0);
+    assert_eq!(
+        w.outcome().unwrap().invalid_phase.as_deref(),
+        Some("alignments")
+    );
+}
+#[test]
+fn democracies_allocate_only_against_predatory_neighbors() {
+    let mut w = fixture(
+        &[0, 1, 2, 3, 4, 5],
+        &[
+            Regime::Democratic,
+            Regime::Democratic,
+            Regime::Predatory,
+            Regime::Predatory,
+            Regime::Predatory,
+            Regime::Predatory,
+        ],
+    );
+    w.engine.allocate(&w.config).unwrap();
+    let id = w.engine.cells[0].owner;
+    let front = w
+        .engine
+        .fronts
+        .values()
+        .find(|f| f.states.contains(&id) && f.states.contains(&w.engine.cells[3].owner))
+        .unwrap();
+    assert_eq!(front.commitments[0], 100.);
+}
+#[test]
+fn extraction_uses_preclaim_territory() {
+    let mut w = fixture(&[0, 0, 2, 3, 4, 5], &[Regime::Predatory; 6]);
+    w.engine.extract(&w.config).unwrap();
+    assert_eq!(w.engine.states[&w.engine.cells[0].owner].resources, 19.5);
+}
+#[test]
+fn capital_collapse_releases_each_primitive_cell() {
+    let mut w = fixture(&[0, 0, 2, 3, 4, 5], &[Regime::Predatory; 6]);
+    let winner = w.engine.cells[3].owner;
+    let loser = w.engine.cells[0].owner;
+    w.engine
+        .apply_claims(
+            &w.config,
+            vec![types::Claim {
+                states: [loser, winner],
+                side: 1,
+                path: [0, 3],
+            }],
+        )
+        .unwrap();
+    assert_eq!(w.engine.states.len(), 6);
+    assert_eq!(w.engine.cells[1].owner.capital_cell, 1);
+    assert_eq!(w.engine.cells[0].owner.sovereignty_generation, 1);
+}
+#[test]
+fn capturing_bridge_releases_disconnected_cells() {
+    let mut w = fixture(&[0, 0, 0, 3, 4, 5], &[Regime::Predatory; 6]);
+    let winner = w.engine.cells[4].owner;
+    let loser = w.engine.cells[0].owner;
+    w.engine
+        .apply_claims(
+            &w.config,
+            vec![types::Claim {
+                states: [loser, winner],
+                side: 1,
+                path: [1, 4],
+            }],
+        )
+        .unwrap();
+    assert_eq!(w.engine.cells[2].owner.capital_cell, 2);
+    assert_eq!(w.engine.cells[1].owner, winner);
+}
+#[test]
